{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Digitoxin, a steroid cardiac glycoside, has essentially complete absolute oral bioavailability in humans (>90%), supporting high F for the steroid-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Perindopril, a small molecule with high assay transfer, shows absolute oral bioavailability 66–95%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C70"],
      "claim": "Ethinylestradiol, a steroid, has absolute oral bioavailability about 54%, supporting high F for the steroid-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Ursodeoxycholic acid, a steroid, has systemic availability about 50%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Lefamulin has absolute oral bioavailability about 26%, above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Amphotericin B has negligible oral bioavailability, but its large polyene macrolide structure and poor permeability make it less applicable to the steroid query; still contradictory.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High-transfer evidence from steroid and small-molecule analogues predominantly supports oral bioavailability ≥20%; the only clear low value is from a structurally dissimilar polyene.",
  "evidence_gaps": [
    "No direct corticosteroid acetal analogue in evidence set",
    "Food effects on bioavailability not specified for query",
    "First-pass metabolism for acetal-containing steroids uncertain"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

